content.content:
vis top keys: ['config', 'grid', 'id', 'type'] required: ['grid', 'type', 'config']
grid {'$ref': '#/components/schemas/Kibana_HTTP_APIs_kbn-dashboard-panel-grid'}
id {'description': 'The unique ID of the panel.', 'type': 'string'}
type {'enum': ['vis'], 'type': 'string'}
dash required: ['title']
options: ['auto_apply_filters', 'hide_panel_borders', 'hide_panel_titles', 'sync_colors', 'sync_cursor', 'sync_tooltips', 'use_margins']
timeRange: {'additionalProperties': False, 'description': 'Specifies the time range for a query.', 'properties': {'from': {'description': 'The start of the time range. Accepts Elasticsearch [date math](https://www.elastic.co/docs/reference/elasticsearch/rest-apis/common-options#date-math) expressions (for example, `now-7d`) or ISO 8601 timestamps.', 'type': 'string'}, 'mode': {'description': 'The time range mode. Use `absolute` for fixed start and end timestamps. Use `relative` for [date math](https://www.elastic.co/docs/reference/elasticsearch/rest-apis/common-options#date-math) expressions that are re-evaluated at query time (for example, `now-7d`).', 'enum': ['absolute', 'relative'], 'type': 'string'}, 'to': {'description': 'The end of the time range. Accepts Elasticsearch [date math](https://www.elastic.co/docs/reference/elasticsearch/rest-apis/common-options#date-math) expressions (for example, `now`) or ISO 8601 timestamps.', 'type': 'string'}}, 'required': ['from', 'to'], 'title': 'Time range', 'type': 'object'}

