input.command:
cd /tmp/eff-0f3slue4/work && S=tmp/claude-0/-tmp-eff-0f3slue4-work/0da1e72d-e9d9-58d9-b388-fca8d0eba393/scratchpad; cat > $S/dash.json <<'EOF'
{
  "title": "S4-77487792 Web logs",
  "options": {"use_margins": true, "sync_colors": false, "sync_cursor": true, "sync_tooltips": false, "hide_panel_titles": false, "auto_apply_filters": true, "hide_panel_borders": false},
  "time_range": {"from": "now-7d", "to": "now", "mode": "relative"},
  "panels": [
    {
      "type": "vis",
      "id": "panel-requests-over-time",
      "grid": {"x": 0, "y": 0, "w": 48, "h": 15},
      "config": {
        "type": "xy",
        "title": "Requests over time",
        "data_source": {"type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247"},
        "layers": [
          {
            "type": "line",
            "data_source": {"type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247"},
            "x": {"operation": "date_histogram", "field": "timestamp"},
            "y": [{"operation": "count", "label": "Requests"}]
          }
        ]
      }
    },
    {
      "type": "vis",
      "id": "panel-requests-by-response",
      "grid": {"x": 0, "y": 15, "w": 48, "h": 15},
      "config": {
        "type": "pie",
        "title": "Requests by response code",
        "data_source": {"type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247"},
        "metrics": [{"operation": "count", "label": "Requests"}],
        "group_by": [{"operation": "terms", "fields": ["response.keyword"], "limit": 20, "label": "HTTP response code"}]
      }
    }
  ]
}
EOF
curl -sS -X POST -H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H "kbn-xsrf: true" -H "Content-Type: application/json" "$KIBANA_URL/api/dashboards" --data-binary @$S/dash.json | tee $S/dash_resp.json | head -c 1500

